begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','96000000-0000-4000-8000-000000000001','authenticated','authenticated','quote-owner@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','96000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"96000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('quotation-test','Quotation Test Legal','Quotation Test','sole_proprietorship','retail','{"city":"Manila"}');
select set_config('test.quote_org',(select id::text from public.organizations where slug='quotation-test'),true);select set_config('test.quote_branch',(select id::text from public.branches where organization_id=current_setting('test.quote_org')::uuid and code='main'),true);
select is(public.can_business_permission(current_setting('test.quote_org')::uuid,'quotations.manage'),true,'Owner receives quotation management permission');
select throws_ok($$select public.save_quotation(current_setting('test.quote_org')::uuid,null,current_setting('test.quote_branch')::uuid,gen_random_uuid(),current_date+30,'','','96000000-0000-4000-8000-000000000001','[]',false)$$,'42501','Permission denied.','Quotation writes require the enabled module');
select public.set_business_module_state(current_setting('test.quote_org')::uuid,'product_catalog',true,'{}');
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.quote_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','96000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"96000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.set_business_module_state(current_setting('test.quote_org')::uuid,'crm',true,'{}');select lives_ok($$select public.set_business_module_state(current_setting('test.quote_org')::uuid,'quotations',true,'{"validity_days":30,"discount_approval_percentage":10,"discount_approver_role":"manager"}')$$,'Quotations module accepts configurable discount approval rules');
select set_config('test.quote_customer',public.save_crm_customer(current_setting('test.quote_org')::uuid,null,current_setting('test.quote_branch')::uuid,'Ana Reyes','09181234567','ana@example.test','{}',null,null,'retail','{}','')::text,true);
select set_config('test.quote_product',public.save_catalog_product(current_setting('test.quote_org')::uuid,null,null,'product','Office Chair','',null,null,'piece',100,60,'inclusive',12,'active',false,'[{"name":"Default","sku":"CHAIR-001","barcode":"4800000000002","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.quote_variant',(select id::text from public.product_variants where product_id=current_setting('test.quote_product')::uuid),true);
select set_config('test.quote_high',public.save_quotation(current_setting('test.quote_org')::uuid,null,current_setting('test.quote_branch')::uuid,current_setting('test.quote_customer')::uuid,current_date+30,'Deliver in Metro Manila','50% down payment','96000000-0000-4000-8000-000000000001',('[{"productVariantId":"'||current_setting('test.quote_variant')||'","quantity":2,"unitPrice":100,"discountAmount":30}]')::jsonb,true)::text,true);
select results_eq($$select quotation_number,revision_number,status,approval_status,subtotal,discount_total,total from public.quotations where id=current_setting('test.quote_high')::uuid$$,$$select 'QUO-'||extract(year from current_date)::integer||'-000001',0,'draft'::text,'pending'::text,200::numeric,30::numeric,170::numeric$$,'High-discount quotation snapshots totals and waits for approval');
select results_eq($$select count(*) from public.quotation_lines where quotation_id=current_setting('test.quote_high')::uuid and product_name='Office Chair'and unit_price=100$$,$$select 1::bigint$$,'Quotation line preserves product and price snapshots');
select results_eq($$select category,status from public.approval_requests where id=(select approval_request_id from public.quotations where id=current_setting('test.quote_high')::uuid)$$,$$select 'discount'::text,'pending'::text$$,'Discount rule creates a reusable approval request');
select public.decide_approval(current_setting('test.quote_org')::uuid,(select approval_request_id from public.quotations where id=current_setting('test.quote_high')::uuid),(select step.id from public.approval_steps step join public.quotations quote on quote.approval_request_id=step.approval_request_id where quote.id=current_setting('test.quote_high')::uuid),'approved','Approved discount');
select results_eq($$select status,approval_status,sent_at is not null from public.quotations where id=current_setting('test.quote_high')::uuid$$,$$select 'sent'::text,'approved'::text,true$$,'Approval automatically sends the quotation');
select lives_ok($$select public.transition_quotation(current_setting('test.quote_org')::uuid,current_setting('test.quote_high')::uuid,'accepted')$$,'Sent quotation can be accepted');
select set_config('test.quote_revision',public.copy_quotation(current_setting('test.quote_org')::uuid,current_setting('test.quote_high')::uuid,true)::text,true);
select results_eq($$select quotation_number,revision_number,status,revision_of_id from public.quotations where id=current_setting('test.quote_revision')::uuid$$,$$select (select quotation_number from public.quotations where id=current_setting('test.quote_high')::uuid),1,'draft'::text,current_setting('test.quote_high')::uuid$$,'Revision keeps the number, increments revision, and starts as a draft');
select set_config('test.quote_duplicate',public.copy_quotation(current_setting('test.quote_org')::uuid,current_setting('test.quote_high')::uuid,false)::text,true);
select isnt((select quotation_number from public.quotations where id=current_setting('test.quote_duplicate')::uuid),(select quotation_number from public.quotations where id=current_setting('test.quote_high')::uuid),'Duplicate receives a new quotation number');
select lives_ok($$select public.queue_quotation_share(current_setting('test.quote_org')::uuid,current_setting('test.quote_high')::uuid,'email','ana@example.test')$$,'Email share is queued for external delivery architecture');
select results_eq($$select channel,delivery_status from public.quotation_shares where quotation_id=current_setting('test.quote_high')::uuid$$,$$select 'email'::text,'queued'::text$$,'Share queue records delivery status');
select set_config('test.quote_order',public.convert_quotation_to_sales_order(current_setting('test.quote_org')::uuid,current_setting('test.quote_high')::uuid)::text,true);
select results_eq($$select status,converted_sales_order_id from public.quotations where id=current_setting('test.quote_high')::uuid$$,$$select 'converted'::text,current_setting('test.quote_order')::uuid$$,'Accepted quotation converts atomically to a sales order');
select results_eq($$select count(*) from public.sales_order_lines where sales_order_id=current_setting('test.quote_order')::uuid$$,$$select 1::bigint$$,'Sales order preserves quotation line snapshots');

select public.set_business_module_state(current_setting('test.quote_org')::uuid,'inventory',true,'{}');select set_config('test.quote_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.quote_org')::uuid),true);select public.set_business_module_state(current_setting('test.quote_org')::uuid,'sales',true,'{}');select public.set_business_module_state(current_setting('test.quote_org')::uuid,'pos',true,'{}');
select set_config('test.quote_sale_source',public.save_quotation(current_setting('test.quote_org')::uuid,null,current_setting('test.quote_branch')::uuid,current_setting('test.quote_customer')::uuid,current_date+30,'','','96000000-0000-4000-8000-000000000001',('[{"productVariantId":"'||current_setting('test.quote_variant')||'","quantity":1,"unitPrice":100,"discountAmount":0}]')::jsonb,true)::text,true);select public.transition_quotation(current_setting('test.quote_org')::uuid,current_setting('test.quote_sale_source')::uuid,'accepted');select set_config('test.quote_sale',public.convert_quotation_to_sale(current_setting('test.quote_org')::uuid,current_setting('test.quote_sale_source')::uuid,current_setting('test.quote_location')::uuid)::text,true);
select results_eq($$select status,total,customer_id from public.sales_transactions where id=current_setting('test.quote_sale')::uuid$$,$$select 'suspended'::text,100::numeric,current_setting('test.quote_customer')::uuid$$,'Accepted quotation converts to a suspended sale without posting payment or stock');
select results_eq($$select unit_price,discount_amount,total from public.sales_lines where sale_id=current_setting('test.quote_sale')::uuid$$,$$select 100::numeric,0::numeric,100::numeric$$,'Sale conversion preserves quoted prices');
select results_eq($$select count(*) from public.quotation_audit_history where quotation_id=current_setting('test.quote_high')::uuid and event in('created','approval_requested','approval_approved','accepted','converted_to_sales_order')$$,$$select 5::bigint$$,'Quotation lifecycle produces complete audit history');
select throws_ok($$update public.quotation_audit_history set details='{}'where quotation_id=current_setting('test.quote_high')::uuid$$,'42501','permission denied for table quotation_audit_history','Clients cannot mutate quotation audit history');
select throws_ok($$select public.transition_quotation(current_setting('test.quote_org')::uuid,current_setting('test.quote_sale_source')::uuid,'accepted')$$,'P0001','Invalid quotation transition.','Converted quotation cannot be accepted again');
select ok(exists(select 1 from public.module_dependencies where module_key='quotations'and dependency_module_key='product_catalog'),'Quotations declares its catalog dependency');
select * from finish();rollback;
